use std :: collections :: HashMap ; use std :: time :: Instant ; use std :: fs ; fn benchmark_large_dataset () -> Vec < BenchmarkResult > { let mut results = Vec :: new () ; println ! ("  📊 Benchmarking 1000 repositories processing...") ; let start = Instant :: now () ; for repo_index in 0 .. 1000 { let mut complexity = 0.0 ; let stars = repo_index * 100 ; let forks = repo_index * 50 ; let contributors = repo_index * 10 ; let size_mb = repo_index * 10 ; let last_commit_days = repo_index % 365 + 1 ; complexity += (stars as f64 + 1.0) . log10 () * 0.25 ; complexity += (forks as f64 + 1.0) . log10 () * 0.15 ; complexity += (contributors as f64 + 1.0) . log10 () * 0.20 ; complexity += (size_mb as f64 + 1.0) . log10 () * 0.10 ; if last_commit_days > 0 { complexity += (365.0 / last_commit_days as f64) . log10 () * 0.10 ; } let family = match complexity { c if c < 1.0 => "Cyclic" , c if c < 2.0 => "Alternating" , c if c < 3.0 => "Lie Type" , _ => "Sporadic" , } ; assert ! (! family . is_empty ()) ; } let duration = start . elapsed () ; let operations_per_second = 1000.0 / (duration . as_millis () as f64 / 1000.0) ; results . push (BenchmarkResult :: new ("1000 Repositories Processing" . to_string () , duration . as_millis () as u64 , operations_per_second , 0.0 , true , None ,)) ; println ! ("  📊 Benchmarking 10000 repositories processing...") ; let start = Instant :: now () ; for repo_index in 0 .. 10000 { let mut complexity = 0.0 ; let stars = repo_index % 100000 ; let forks = repo_index % 50000 ; let contributors = repo_index % 1000 ; let size_mb = repo_index % 1000 ; let last_commit_days = repo_index % 365 + 1 ; complexity += (stars as f64 + 1.0) . log10 () * 0.25 ; complexity += (forks as f64 + 1.0) . log10 () * 0.15 ; complexity += (contributors as f64 + 1.0) . log10 () * 0.20 ; complexity += (size_mb as f64 + 1.0) . log10 () * 0.10 ; if last_commit_days > 0 { complexity += (365.0 / last_commit_days as f64) . log10 () * 0.10 ; } let family = match complexity { c if c < 1.0 => "Cyclic" , c if c < 2.0 => "Alternating" , c if c < 3.0 => "Lie Type" , _ => "Sporadic" , } ; assert ! (! family . is_empty ()) ; } let duration = start . elapsed () ; let operations_per_second = 10000.0 / (duration . as_millis () as f64 / 1000.0) ; results . push (BenchmarkResult :: new ("10000 Repositories Processing" . to_string () , duration . as_millis () as u64 , operations_per_second , 0.0 , true , None ,)) ; results }